namespace Engine.ViewModels;
using Newtonsoft.Json;
using Engine.Models;
using Engine.Factories;
using System.Linq;
using Engine.EventArgs;
using Engine.Services;


public class GameSession : BaseNotificationClass
{
    private readonly MessageBroker _messageBroker = MessageBroker.GetInstance();
    private Battle _currentBattle;
    private Location _currentLocation = null!;
    private Monster? _currentMonster;
    private Player _currentPlayer = null!;
    private Trader? _currentTrader;

    public string Version = "0.1.000";
    [JsonIgnore]
    public World CurrentWorld { get; }
    public Player CurrentPlayer {
        get{return _currentPlayer;}
        set{
            if(_currentPlayer != null)
            {
                _currentPlayer.OnLeveledUp -= OnCurrentPlayerLeveledUp;
                _currentPlayer.OnKilled -= OnPlayerKilled;
            }
            _currentPlayer = value;
            if(_currentPlayer != null)
            {
                _currentPlayer.OnLeveledUp += OnCurrentPlayerLeveledUp;
                _currentPlayer.OnKilled += OnPlayerKilled;
            }
            OnPropertyChanged();
        }
    }
    public Location CurrentLocation {
    get{return _currentLocation;}
    set{
        _currentLocation = value;
        OnPropertyChanged();
        OnPropertyChanged(nameof(HasLocationToNorth));
        OnPropertyChanged(nameof(HasLocationToWest));
        OnPropertyChanged(nameof(HasLocationToEast));
        OnPropertyChanged(nameof(HasLocationToSouth));

        CompleteQuestsAtLocation();
        GivePlayerQuestsAtLocation();
        CurrentMonster = CurrentLocation.GetMonster();

        CurrentTrader = CurrentLocation.TraderHere;
        }
    }
    [JsonIgnore]
    public Monster? CurrentMonster
    {
        get{return _currentMonster;}
        set{
            if(_currentMonster != null)
            {
                _currentBattle.OnCombatVictory -= OnCurrentMonsterKilled;
                _currentBattle.Dispose();
            }
            _currentMonster = value;

            if(_currentMonster != null)
            {
                _currentBattle = new Battle(CurrentPlayer, CurrentMonster);
                _currentBattle.OnCombatVictory += OnCurrentMonsterKilled;
            }
            OnPropertyChanged();
            OnPropertyChanged(nameof(HasMonster));
        }
    }
    [JsonIgnore]
    public Trader? CurrentTrader
    {
        get{return _currentTrader;}
        set
        {
            _currentTrader = value;
            OnPropertyChanged();
            OnPropertyChanged(nameof(HasTrader));
        }
    }
    [JsonIgnore]
    public bool HasLocationToNorth => CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate + 1) != null;
    [JsonIgnore]
    public bool HasLocationToWest => CurrentWorld.LocationAt(CurrentLocation.XCoordinate - 1, CurrentLocation.YCoordinate) != null;
    [JsonIgnore]
    public bool HasLocationToEast => CurrentWorld.LocationAt(CurrentLocation.XCoordinate + 1, CurrentLocation.YCoordinate) != null;
    [JsonIgnore]
    public bool HasLocationToSouth =>  CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate - 1) != null;
    [JsonIgnore]
    public bool HasMonster => CurrentMonster != null;
    [JsonIgnore]
    public bool HasTrader => CurrentTrader != null;

    public GameSession()
    {
        CurrentWorld = WorldFactory.CreateWorld();
        CurrentPlayer = new Player("Jakob", "Warrior", experience: 0, maximumHitPoints: 100, currentHitPoints: 100, dexterity: 5, gold: 0);

        if (!CurrentPlayer.Inventory.Weapons.Any())
        {
            CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(1001));
        }
        CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(2001));
        CurrentPlayer.LearnRecipe(RecipeFactory.RecipeByID(1));
        CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(3001));
        CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(3002));
        CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(3003));

        CurrentLocation = HomeLocation();
    }
    public GameSession(Player player, int xCoordinate, int yCoordinate)
    {
        CurrentWorld = WorldFactory.CreateWorld();
        CurrentPlayer = player;
        CurrentLocation = CurrentWorld.LocationAt(xCoordinate, yCoordinate);
    }

    private Location HomeLocation()
    {
        return CurrentWorld.LocationAt(0, -1)
            ?? throw new InvalidOperationException("The world has no location at (0, -1) to use as Home.");
    }

    public void MoveNorth()
    {
        MoveTo(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate + 1);
    }

    public void MoveWest()
    {
        MoveTo(CurrentLocation.XCoordinate - 1, CurrentLocation.YCoordinate);
    }

    public void MoveEast()
    {
        MoveTo(CurrentLocation.XCoordinate + 1, CurrentLocation.YCoordinate);
    }

    public void MoveSouth()
    {
        MoveTo(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate - 1);
    }

    private void MoveTo(int xCoordinate, int yCoordinate)
    {
        Location? destination = CurrentWorld.LocationAt(xCoordinate, yCoordinate);
        if (destination != null)
        {
            CurrentLocation = destination;
        }
    }

    private void GivePlayerQuestsAtLocation()
    {
        foreach (Quest quest in CurrentLocation.QuestsAvailableHere)
        {
            if (!CurrentPlayer.Quests.Any(q => q.Quest.Id == quest.Id))
            {
                CurrentPlayer.Quests.Add(new QuestStatus(quest));
                _messageBroker.RaiseMessage("");
                _messageBroker.RaiseMessage($"You received the {quest.Name} quest");
                _messageBroker.RaiseMessage(quest.Description);
                _messageBroker.RaiseMessage("return with:");
                foreach(ItemQuantity item in quest.CompleteItems)
                {
                    _messageBroker.RaiseMessage($"   {item.Quantity} {ItemFactory.CreateGameItem(item.ItemID).Name}");
                }
                _messageBroker.RaiseMessage("And you will receive");
                _messageBroker.RaiseMessage($"   {quest.RewardExperiencePoints} experience points");
                _messageBroker.RaiseMessage($"   {quest.RewardGold} gold");
                foreach(ItemQuantity itemQuantity in quest.RewardItems)
                {
                    _messageBroker.RaiseMessage($"   {itemQuantity.Quantity} {ItemFactory.CreateGameItem(itemQuantity.ItemID).Name}");
                }
            }
        }
    }

    private void CompleteQuestsAtLocation()
    {
        foreach(Quest quest in CurrentLocation.QuestsAvailableHere)
        {
            QuestStatus? questToComplete =
                CurrentPlayer.Quests.FirstOrDefault(q => q.Quest.Id == quest.Id &&
                                                            !q.IsCompleted);

            if(questToComplete != null)
            {
                if(CurrentPlayer.Inventory.HasAllTheseItems(quest.CompleteItems))
                {
                    CurrentPlayer.RemoveItemsFromInventory(quest.CompleteItems); 
                    _messageBroker.RaiseMessage("");
                    _messageBroker.RaiseMessage($"You completed the '{quest.Name}' quest");

                    // Give the player the quest rewards
                    _messageBroker.RaiseMessage($"You receive {quest.RewardExperiencePoints} experience points");
                    CurrentPlayer.AddExperience(quest.RewardExperiencePoints);

                    _messageBroker.RaiseMessage($"You receive {quest.RewardGold} gold");        
                    CurrentPlayer.ReceiveGold(quest.RewardGold);


                    foreach(ItemQuantity itemQuantity in quest.RewardItems)
                    {
                        GameItem rewardItem = ItemFactory.CreateGameItem(itemQuantity.ItemID);

                        _messageBroker.RaiseMessage($"You receive a {rewardItem.Name}");
                        CurrentPlayer.AddItemToInventory(rewardItem);
                    }

                    // Mark the Quest as completed
                    questToComplete.IsCompleted = true;
                }
            }
        }
    }
    private void GetMonsterAtLocation()
    {
        CurrentMonster = CurrentLocation.GetMonster();
    }

    public void AttackCurrentMonster()
    {
        _currentBattle.AttackOpponent();
    }

    public void UseCurrentConsumables()
    {
        if (CurrentPlayer.CurrentConsumable == null)
        {
            _messageBroker.RaiseMessage("You must select a consumable");
            return;
        }
        CurrentPlayer.UseCurrentConsumable();
    }

    public void CraftItemUsing(Recipe recipe)
    {
        if (CurrentPlayer.Inventory.HasAllTheseItems(recipe.Ingredients))
        {
            CurrentPlayer.RemoveItemsFromInventory(recipe.Ingredients);
            foreach(ItemQuantity itemQuantity in recipe.OutputItems)
            {
                for(int i = 0; i < itemQuantity.Quantity; i++)
                {   
                    GameItem outputItem = ItemFactory.CreateGameItem(itemQuantity.ItemID);
                    CurrentPlayer.AddItemToInventory(outputItem);
                    _messageBroker.RaiseMessage($"You crafted 1 {outputItem.Name}");
                }
            }
        }
        else
        {
            _messageBroker.RaiseMessage("You dont have the requiered ingredients:");
            foreach(ItemQuantity itemQuantity in recipe.Ingredients)
            {
                _messageBroker.RaiseMessage($"{itemQuantity.Quantity} {ItemFactory.ItemName(itemQuantity.ItemID)}");
            }
        }
    }

    private void OnPlayerKilled(object? sender, System.EventArgs eventArgs)
    {
        _messageBroker.RaiseMessage("");
        _messageBroker.RaiseMessage("You have been killed");

        CurrentLocation = HomeLocation();
        CurrentPlayer.CompleteHeal();
    }

    private void OnCurrentMonsterKilled(object? sender, System.EventArgs eventArgs)
    {
        CurrentMonster = CurrentLocation.GetMonster();
    }

    private void OnCurrentPlayerLeveledUp(object? sender, System.EventArgs eventArgs)
    {
        _messageBroker.RaiseMessage($"You are now Level {CurrentPlayer.Level}");
    }
}

