using System.Collections.ObjectModel;
namespace Engine.Models;

public class Player : LivingEntity
{
    private string _characterClass = string.Empty;
    private int _experiencePoints;

    public string CharacterClass
    { get{return _characterClass;}
    set{
        _characterClass = value;
        OnPropertyChanged();
    }
    }
    public int Experience {
        get { return _experiencePoints; }
        private set { _experiencePoints = value;
        OnPropertyChanged();
        }
    }

    public ObservableCollection<QuestStatus> Quests { get; }
    public ObservableCollection<Recipe> Recipes {get ;}

    public event EventHandler? OnLeveledUp;

    public Player(string name, string characterClass, int experience, int maximumHitPoints, int currentHitPoints,int dexterity, int gold) :
    base(name, maximumHitPoints, currentHitPoints,dexterity, gold)
    {
        CharacterClass = characterClass;
        Experience = experience;
        // Derive the starting level from experience, but keep the maximumHitPoints we were
        // given - recalculating it here would silently discard the caller's value.
        Level = LevelForExperience(Experience);
        Quests = new ObservableCollection<QuestStatus>();
        Recipes = new ObservableCollection<Recipe>();
    }

    public void AddExperience(int value)
    {
        Experience += value;
        SetLevelAndMaximumHitPoints();
    }
    public void LearnRecipe(Recipe recipe)
    {
        if(!Recipes.Any(r => r.ID == recipe.ID))
        {
            Recipes.Add(recipe);
        }
    }

    private static int LevelForExperience(int experience)
    {
        return (experience / 100) + 1;
    }

    private void SetLevelAndMaximumHitPoints()
    {
        int originalLevel = Level;
        Level = LevelForExperience(Experience);
        if(Level != originalLevel)
        {
            MaximumHitPoints = Level * 10;
            OnLeveledUp?.Invoke(this, System.EventArgs.Empty);
        }
    }
}

